def hidden_rule_fn(state):
    # Identify BLINX and TORVE particles
    blinx_particles = [(p['x'], p['y']) for p in state if p['type'] == 'BLINX']
    torve_particles = [(p['x'], p['y']) for p in state if p['type'] == 'TORVE']

    def wrap_dir(delta):
        """Compute direction for a coordinate displacement on 8x8 toroidal grid.
        delta = (target - source) mod 8, then direction is:
        - 0 if delta == 0
        - +1 if 1 <= delta <= 4
        - -1 if 5 <= delta <= 7
        """
        d = delta % 8
        if d == 0:
            return 0
        elif d <= 4:
            return 1
        else:
            return -1

    def chebyshev_dist(p1, p2):
        """Chebyshev distance on 8x8 toroidal grid."""
        dx = min(abs(p1[0] - p2[0]), 8 - abs(p1[0] - p2[0]))
        dy = min(abs(p1[1] - p2[1]), 8 - abs(p1[1] - p2[1]))
        return max(dx, dy)

    def find_nearest(p, targets):
        """Find the nearest target to point p by Chebyshev distance.
        Ties broken by lexicographic ordering (smallest x, then smallest y).
        Returns the nearest target tuple, or None if no targets.
        """
        if not targets:
            return None
        best = min(targets, key=lambda t: (chebyshev_dist(p, t), t[0], t[1]))
        return best

    def move_towards(p, target):
        """Move one step towards target on toroidal grid."""
        dx = wrap_dir(target[0] - p[0])
        dy = wrap_dir(target[1] - p[1])
        return ((p[0] + dx) % 8, (p[1] + dy) % 8)

    def move_away(p, target):
        """Move one step away from target on toroidal grid."""
        dx = -wrap_dir(target[0] - p[0])
        dy = -wrap_dir(target[1] - p[1])
        return ((p[0] + dx) % 8, (p[1] + dy) % 8)

    def splurn(p, q):
        """Parity of total coordinate sum of two particles."""
        return (p[0] + p[1] + q[0] + q[1]) % 2

    next_state = []

    for p in state:
        if p['type'] == 'BLINX':
            nearest_torve = find_nearest((p['x'], p['y']), torve_particles)
            if nearest_torve is None:
                # No TORVEs, BLINX stays
                next_state.append({'type': 'BLINX', 'x': p['x'], 'y': p['y']})
            else:
                s = splurn((p['x'], p['y']), nearest_torve)
                if s == 0:
                    # Move towards nearest TORVE
                    new_pos = move_towards((p['x'], p['y']), nearest_torve)
                else:
                    # Move away from nearest TORVE
                    new_pos = move_away((p['x'], p['y']), nearest_torve)
                next_state.append({'type': 'BLINX', 'x': new_pos[0], 'y': new_pos[1]})
        elif p['type'] == 'TORVE':
            nearest_blinx = find_nearest((p['x'], p['y']), blinx_particles)
            if nearest_blinx is None:
                # No BLINXs, TORVE stays
                next_state.append({'type': 'TORVE', 'x': p['x'], 'y': p['y']})
            else:
                s = splurn((p['x'], p['y']), nearest_blinx)
                if s == 0:
                    # Move towards nearest BLINX
                    new_pos = move_towards((p['x'], p['y']), nearest_blinx)
                else:
                    # Stay in place
                    new_pos = (p['x'], p['y'])
                next_state.append({'type': 'TORVE', 'x': new_pos[0], 'y': new_pos[1]})

    return next_state
